const logEl = document.getElementById('console');
        const radarStatus = document.getElementById('radar-status');
        const scanIndicator = document.getElementById('scan-indicator');
        const pulse = document.getElementById('signal-pulse');
        function appendLog(msg, type = 'INFO') {
            const time = new Date().toLocaleTimeString().split(' ')[0];
            let color = 'text-slate-500';
            if (type === 'ERR') color = 'text-red-500';
            if (type === 'SUCCESS') color = 'text-emerald-400';
            if (type === 'WARN') color = 'text-amber-500';
            logEl.innerHTML += `<div class="${color}">[${time}] [${type}] ${msg}</div>`;
            logEl.scrollTop = logEl.scrollHeight;
        }
        async function requestDevice() {
            if (!navigator.bluetooth) {
                appendLog("Web Bluetooth not supported on this browser context.", "ERR");
                return;
            }
            try {
                radarStatus.innerText = "SCANNING...";
                radarStatus.classList.add('animate-pulse');
                scanIndicator.classList.remove('opacity-0');
                pulse.classList.remove('opacity-0');
                appendLog("Requesting BLE peripheral acquisition...");
                const device = await navigator.bluetooth.requestDevice({
                    acceptAllDevices: true,
                    // Note: Optional services must be listed to access them later
                    optionalServices: ['generic_access', 'device_information', 'battery_service', 'heart_rate']
                });
                appendLog(`Target acquired: ${device.name || 'Unnamed Node'}`, "SUCCESS");
                appendLog(`Hardware ID: ${device.id.substring(0, 16)}...`);
                device.addEventListener('gattserverdisconnected', onDisconnected);
                appendLog("Initiating GATT handshake protocol...");
                const server = await device.gatt.connect();
                appendLog("GATT connection verified.", "SUCCESS");
                const services = await server.getPrimaryServices();
                appendLog(`Found ${services.length} active primary services. Map initialized.`);
                services.forEach(s => {
                    appendLog(`Service UUID mapped: ${s.uuid.toUpperCase()}`);
                });
                radarStatus.innerText = "CONNECTED";
                radarStatus.classList.remove('animate-pulse');
            } catch (error) {
                appendLog(error.message, "ERR");
                radarStatus.innerText = "FAILED";
                radarStatus.classList.remove('animate-pulse');
            } finally {
                scanIndicator.classList.add('opacity-0');
                pulse.classList.add('opacity-0');
            }
        }
        function onDisconnected(event) {
            appendLog("Remote link severed / Device disconnected.", "WARN");
            radarStatus.innerText = "IDLE";
        }
        function clearConsole() {
            logEl.innerHTML = "";
            appendLog("Volatile memory purged. System idle.");
        }
